import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CrtMatrixProps = Record<string, any>;

// Character sets for Matrix rain
const KATAKANA = "ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ";
const LATIN = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
const CHARS = KATAKANA + LATIN;

// --- Sub-Components ---

const MatrixColumn: React.FC<{ x: number, delay: number, speed: number, primaryColor: string }> = React.memo(({ x, delay, speed, primaryColor }) => {
  const frame = useCurrentFrame();
  const activeFrame = frame - delay;

  // Mask moves down to reveal/hide trails
  const maskY = activeFrame * speed;

  // Change characters randomly but slower to optimize performance and reduce lag
  const textSeed = Math.floor(frame / 15); 
  const textStr = useMemo(() => {
    // Reduced length to 40 lines (sufficient to cover 1080px at 30px lineHeight) to save rendering cost
    return Array.from({ length: 40 }).map((_, i) => CHARS[Math.floor(random(`col-${x}-${i}-${textSeed}`) * CHARS.length)]).join('\n');
  }, [textSeed, x]);

  if (activeFrame < -50 || maskY > 2000) return null;

  return (
    <div style={{
      position: 'absolute', left: x, top: 0, bottom: 0, width: 32,
      fontFamily: '"Share Tech Mono", monospace', fontSize: 26, lineHeight: '30px',
      color: primaryColor, textAlign: 'center', opacity: 0.85,
      textShadow: `0 0 10px ${primaryColor}`,
      transition: 'none'
    }}>
      {/* Fading Trail */}
      <div style={{
        WebkitMaskImage: `linear-gradient(to bottom, transparent ${maskY - 500}px, black ${maskY}px, transparent ${maskY + 20}px)`,
        maskImage: `linear-gradient(to bottom, transparent ${maskY - 500}px, black ${maskY}px, transparent ${maskY + 20}px)`,
        transition: 'none'
      }}>
        <div style={{ whiteSpace: 'pre', transition: 'none' }}>{textStr}</div>
      </div>
      {/* Bright Solid Head */}
      <div style={{
        position: 'absolute', inset: 0, color: 'white',
        textShadow: `0 0 10px white, 0 0 25px ${primaryColor}, 0 0 40px ${primaryColor}`,
        WebkitMaskImage: `linear-gradient(to bottom, transparent ${maskY - 40}px, black ${maskY}px, transparent ${maskY + 5}px)`,
        maskImage: `linear-gradient(to bottom, transparent ${maskY - 40}px, black ${maskY}px, transparent ${maskY + 5}px)`,
        transition: 'none'
      }}>
        <div style={{ whiteSpace: 'pre', transition: 'none' }}>{textStr}</div>
      </div>
    </div>
  );
});

const MatrixRainContainer: React.FC<{ startFrame: number, primaryColor: string, density: number }> = React.memo(({ startFrame, primaryColor, density }) => {
  // Map density slider to a more sensible column count to prevent extreme DOM node explosion and lag
  const columnsCount = Math.floor(interpolate(density, [10, 100], [20, 120]));
  const columnWidth = 1920 / columnsCount;

  const columns = useMemo(() => {
    return Array.from({ length: columnsCount }).map((_, i) => {
      // Reduced layers from 3 to 2 to significantly cut down DOM elements while maintaining depth
      return [0, 1].map(layer => ({
        id: `${i}-${layer}`,
        x: i * columnWidth + (random(`x-${i}-${layer}`) * 20 - 10), // Adding layer to random seed for better distribution
        speed: random(`speed-${i}-${layer}`) * 12 + 15,
        delay: startFrame + layer * 150 + random(`delay-${i}-${layer}`) * 100
      }));
    }).flat();
  }, [columnsCount, columnWidth, startFrame]);

  return (
    <AbsoluteFill style={{ overflow: 'hidden', transition: 'none' }}>
      {columns.map(col => (
        <MatrixColumn key={col.id} x={col.x} delay={col.delay} speed={col.speed} primaryColor={primaryColor} />
      ))}
    </AbsoluteFill>
  );
});

const LockingLetter: React.FC<{ targetChar: string, lockFrame: number, seed: number, primaryColor: string, tBloom: number }> = React.memo(({ targetChar, lockFrame, seed, primaryColor, tBloom }) => {
  const frame = useCurrentFrame();
  const isLocked = frame >= lockFrame;
  const textSeed = Math.floor(frame / 6); // Slightly slower scrambling for the final text for clarity

  const displayChar = isLocked || targetChar === ' '
    ? targetChar
    : CHARS[Math.floor(random(`scramble-${seed}-${textSeed}`) * CHARS.length)];

  const bloomProgress = interpolate(frame, [tBloom, tBloom + 15, tBloom + 45], [0, 1, 0.2], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const pulseScale = isLocked ? interpolate(bloomProgress, [0, 1], [1, 1.05]) : 1;
  const glow = isLocked ? interpolate(bloomProgress, [0, 1], [15, 60]) : 5;
  const brightness = isLocked ? interpolate(bloomProgress, [0, 1], [1, 2]) : 1;
  const color = isLocked ? (bloomProgress > 0.5 ? '#ffffff' : primaryColor) : primaryColor;

  return (
    <span style={{
      color: color,
      textShadow: isLocked
        ? `0 0 10px white, 0 0 ${glow}px ${primaryColor}, 0 0 ${glow * 2}px ${primaryColor}`
        : `0 0 8px ${primaryColor}`,
      filter: `brightness(${brightness})`,
      transform: `scale(${pulseScale})`,
      display: 'inline-block',
      width: targetChar === ' ' ? '0.4em' : '1.1em',
      textAlign: 'center',
      transition: 'none'
    }}>
      {displayChar}
    </span>
  );
});


// --- Main Component ---

const CrtMatrix: React.FC<CrtMatrixProps> = ({
  backgroundColor = "#020302",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryColor = "#22ff44",
  finalText = "MALLOY STUDIO",
  finalTextSize = 130,
  matrixDensity = 50,
}) => {
  useFontLoader(["Share Tech Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Timeline Calculations ---
  const totalFrames = durationInSeconds * fps;
  const tZoomStart = totalFrames * 0.15;
  const tZoomEnd = totalFrames * 0.45;
  const tSignalOff = totalFrames * 0.40;
  const tRainStart = totalFrames * 0.42;
  const tLockStart = totalFrames * 0.70;
  const tBloom = totalFrames * 0.85;

  const bgColor = transparentBackground ? `transparent` : backgroundColor;

  // --- Zoom Animation ---
  const zoomProgress = interpolate(frame, [tZoomStart, tZoomEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  // Base scale starts zoomed out to see the whole monitor. Target scale fits exactly inner screen.
  // The monitor outer bezel is 2800x1800. The inner screen is exactly 1920x1080.
  // To fill 1920x1080 video with the 1920x1080 inner screen, target scale is exactly 1.0 (plus a tiny bleed).
  // Base scale calculates how much to shrink the 2800 width to fit nicely in 1920.
  const baseScale = width / 3400; // Leaves nice margin around monitor
  const targetScale = 1.01; // Slight overscan to hide bezels completely
  const currentScale = interpolate(zoomProgress, [0, 1], [baseScale, targetScale]);

  const yOffset = interpolate(zoomProgress, [0, 1], [150, 0]); // Moves monitor slightly up initially

  // --- Signal Text Animation ---
  const showSignal = frame < tSignalOff;
  const signalBlink = interpolate((frame % 60), [0, 30, 31, 60], [1, 1, 0, 0]);

  // --- Locking Text Animation ---
  const letters = finalText.split('');
  const lockDuration = tBloom - tLockStart;
  const stagger = lockDuration / Math.max(letters.length, 1);
  const showLockingText = frame > tLockStart - 30; // Fade in slightly before locking

  const lockContainerOpacity = interpolate(frame, [tLockStart - 30, tLockStart], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: 'hidden' }}>
      
      {/* Background Room Glow */}
      {!transparentBackground && (
        <AbsoluteFill style={{
          background: `radial-gradient(circle at center 60%, #0a140a 0%, ${backgroundColor} 70%)`,
          opacity: interpolate(zoomProgress, [0, 1], [1, 0]), // Fade out room as we zoom
          transition: "none"
        }} />
      )}

      {/* Main Transform Container for Zoom */}
      <AbsoluteFill style={{
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        transform: `scale(${currentScale}) translateY(${yOffset}px)`,
        transformOrigin: 'center center',
        transition: "none"
      }}>
        
        {/* CRT Monitor Outer Assembly */}
        <div style={{ position: 'relative', width: 2800, height: 1800, display: 'flex', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
          
          {/* Monitor Stand */}
          <div style={{
            position: 'absolute', top: 1600, width: 1000, height: 300,
            backgroundColor: '#0a0a0a', borderTopLeftRadius: 80, borderTopRightRadius: 80,
            boxShadow: 'inset 0 10px 30px rgba(255,255,255,0.02), 0 50px 100px rgba(0,0,0,0.9)',
            transition: "none"
          }}>
            {/* Vents/Details on stand */}
            <div style={{ display: 'flex', gap: 20, justifyContent: 'center', marginTop: 150, transition: "none" }}>
              {[1,2,3,4,5,6].map(i => (
                <div key={i} style={{ width: 40, height: 10, backgroundColor: '#22ff44', opacity: 0.3, borderRadius: 5, boxShadow: '0 0 10px #22ff44', transition: "none" }} />
              ))}
            </div>
          </div>

          {/* Main Bezel Container */}
          <div style={{
            width: 2500, height: 1600,
            backgroundColor: '#151515', borderRadius: 120,
            boxShadow: '0 50px 150px rgba(0,0,0,0.9), inset 0 15px 40px rgba(255,255,255,0.05), inset 0 -20px 60px rgba(0,0,0,0.8)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative', zIndex: 10,
            transition: "none"
          }}>
            
            {/* Inner Bezel / Tube Edge */}
            <div style={{
              width: 2080, height: 1240,
              backgroundColor: '#050505', borderRadius: 80,
              boxShadow: 'inset 0 30px 80px rgba(0,0,0,1)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              transition: "none"
            }}>
              
              {/* Actual Screen Area (Exactly 1920x1080) */}
              <div style={{
                width: 1920, height: 1080,
                backgroundColor: '#020602',
                borderRadius: '40px', // Simulated curvature
                position: 'relative', overflow: 'hidden',
                transition: "none"
              }}>
                
                {/* Screen Content Root */}
                <AbsoluteFill style={{ transition: "none" }}>
                  
                  {/* Initial Signal Text */}
                  {showSignal && (
                    <AbsoluteFill style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
                      <div style={{
                        fontFamily: '"Share Tech Mono", monospace', fontSize: 60, color: primaryColor,
                        opacity: signalBlink, textShadow: `0 0 20px ${primaryColor}`, letterSpacing: 10,
                        transition: "none"
                      }}>
                        SIGNAL DETECTED
                      </div>
                    </AbsoluteFill>
                  )}

                  {/* Matrix Rain */}
                  {frame >= tRainStart && (
                    <MatrixRainContainer startFrame={tRainStart} primaryColor={primaryColor} density={matrixDensity} />
                  )}

                  {/* Overlay Mask to darken rain behind text */}
                  {showLockingText && (
                    <AbsoluteFill style={{
                      background: `radial-gradient(ellipse at center, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 50%)`,
                      opacity: lockContainerOpacity,
                      transition: "none", zIndex: 15
                    }} />
                  )}

                  {/* Locking Final Text */}
                  {showLockingText && (
                    <AbsoluteFill style={{
                      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 20,
                      opacity: lockContainerOpacity, transition: "none"
                    }}>
                      <div style={{
                        fontFamily: '"Share Tech Mono", monospace', fontSize: finalTextSize, fontWeight: 'bold',
                        display: 'flex', gap: 5, transition: "none"
                      }}>
                        {letters.map((char, idx) => (
                          <LockingLetter
                            key={idx}
                            targetChar={char}
                            lockFrame={tLockStart + (idx * stagger)}
                            seed={idx}
                            primaryColor={primaryColor}
                            tBloom={tBloom}
                          />
                        ))}
                      </div>
                    </AbsoluteFill>
                  )}

                </AbsoluteFill>

                {/* CRT Screen Overlays (Curvature, Vignette, Scanlines) */}
                <AbsoluteFill style={{
                  background: 'radial-gradient(circle at center, transparent 40%, rgba(0,0,0,0.8) 120%)',
                  boxShadow: 'inset 0 0 100px rgba(0,0,0,0.9), inset 0 0 30px rgba(255,255,255,0.05)',
                  pointerEvents: 'none', zIndex: 50, transition: "none"
                }} />
                
                {/* Scanlines Pattern */}
                <AbsoluteFill style={{
                  background: `linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.3) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))`,
                  backgroundSize: '100% 6px, 12px 100%',
                  pointerEvents: 'none', zIndex: 60, mixBlendMode: 'overlay', transition: "none"
                }} />

              </div>
            </div>
          </div>
        </div>
      </AbsoluteFill>
      
      {/* Global Vignette to enhance dark room feel during zoom */}
      <AbsoluteFill style={{
        background: 'radial-gradient(circle at center, transparent 50%, rgba(0,0,0,0.6) 100%)',
        pointerEvents: 'none', zIndex: 100, transition: "none"
      }} />

    </AbsoluteFill>
  );
};

export default CrtMatrix;